package service

import (
	"regexp"

	"github.com/google/uuid"

	"groundwork/internal/repository"
)

// Lowercase Crockford base32, as generated by gen_short_id() in migration 008.
var shortIDPattern = regexp.MustCompile(`^[0-9a-hjkmnp-tv-z]{8}$`)

// RefService turns the {id} in a URL into a UUID. URLs carry either the UUID or the
// short ID. found is false when the ref names nothing; ownership is checked later,
// by the query that loads the row, so a UUID is returned without a lookup.
type RefService interface {
	ParcelID(ref string) (id uuid.UUID, found bool, err error)
	SnapshotID(ref string) (id uuid.UUID, found bool, err error)
}

type refService struct {
	repo repository.RefRepository
}

func NewRefService(repo repository.RefRepository) RefService {
	return &refService{repo: repo}
}

func (s *refService) ParcelID(ref string) (uuid.UUID, bool, error) {
	return resolveRef(ref, s.repo.ParcelIDByShortID)
}

func (s *refService) SnapshotID(ref string) (uuid.UUID, bool, error) {
	return resolveRef(ref, s.repo.SnapshotIDByShortID)
}

func resolveRef(ref string, byShortID func(string) (uuid.UUID, bool, error)) (uuid.UUID, bool, error) {
	if id, err := uuid.Parse(ref); err == nil {
		return id, true, nil
	}
	if !shortIDPattern.MatchString(ref) {
		return uuid.Nil, false, nil
	}
	return byShortID(ref)
}
